# ============================================================
#  聚合器
# ============================================================
class Spider(BaseSpider):
    def getName(self):
        return 'py聚合'

    def init(self, extend=''):
        self.subs = {}
        self.home_cache = {}
        self.img_cache = {}
        self.failed = {}
        self.area_cache = {}
        self.lock = threading.Lock()
        self.meta = {s[0]: s for s in SITES}
        self.cache_dir = os.path.join(tempfile.gettempdir(), 'py_juhe')
        try:
            os.makedirs(self.cache_dir, exist_ok=True)
        except Exception:
            pass

    # ---------- 网络（多 UA 轮换） ----------
    def fetch(self, url, headers=None, timeout=10, **kw):
        hd = {'User-Agent': random.choice(UAS)}
        hd.update(headers or {})
        return BaseSpider.fetch(self, url, headers=hd, timeout=timeout, **kw)

    def post(self, url, data=None, json=None, headers=None, timeout=10, **kw):
        hd = {'User-Agent': random.choice(UAS)}
        hd.update(headers or {})
        if json is not None:
            return BaseSpider.post(self, url, json=json, headers=hd, timeout=timeout, **kw)
        return BaseSpider.post(self, url, data=data, headers=hd, timeout=timeout, **kw)

    # ---------- 子站加载 ----------
    def _py_source(self, key, url):
        path = os.path.join(self.cache_dir, key + '.py')
        fresh = os.path.exists(path) and time.time() - os.path.getmtime(path) < 86400
        if not fresh:
            try:
                r = self.fetch(url, headers={'User-Agent': 'okhttp/4.12.0'}, timeout=25)
                txt = r.content.decode('utf-8', 'ignore')
                if 'class Spider' in txt:
                    with open(path, 'w', encoding='utf-8') as f:
                        f.write(txt)
                    return txt
            except Exception:
                pass
        if os.path.exists(path):
            with open(path, encoding='utf-8') as f:
                return f.read()
        return ''

    def sub(self, key):
        if key in self.subs:
            return self.subs[key]
        if time.time() - self.failed.get(key, 0) < 120:
            return None
        with self.lock:
            if key in self.subs:
                return self.subs[key]
            _, name, kind, arg, _s = self.meta[key]
            obj = None
            try:
                if kind in ('py', 'embed'):
                    if kind == 'embed':
                        import zlib
                        src = zlib.decompress(base64.b85decode(EMBED[arg])).decode('utf-8', 'ignore')
                    else:
                        src = self._py_source(key, arg)
                    if src:
                        mod = types.ModuleType('kl_' + key)
                        mod.__file__ = os.path.join(self.cache_dir, key + '.py')
                        exec(compile(src, mod.__file__, 'exec'), mod.__dict__)
                        obj = mod.Spider()
                        try:
                            orig = obj.getProxyUrl

                            def gp(*a, _o=orig, _k=key, **k):
                                return _o(*a, **k) + '&klsite=' + _k
                            obj.getProxyUrl = gp
                        except Exception:
                            pass
                        try:
                            obj.init('')
                        except TypeError:
                            obj.init()
                else:
                    obj = BUILTIN[kind](self, arg)
                    obj.init('')
            except Exception:
                obj = None
            if obj is None:
                self.failed[key] = time.time()
            else:
                self.subs[key] = obj
            return obj

    def call(self, key, fn, *a):
        s = self.sub(key)
        if s is None:
            return {}
        try:
            r = getattr(s, fn)(*a)
            if isinstance(r, str):
                r = json.loads(r) if r.strip().startswith('{') else {}
            return r or {}
        except Exception:
            return {}

    # ---------- 工具 ----------
    def wrap(self, key, vods):
        out = []
        for v in vods or []:
            vid = str(v.get('vod_id', ''))
            name = str(v.get('vod_name', ''))
            if not vid or PROMO.search(name) or vid.startswith('pinned') or any(w in name for w in BLOCK_WORDS):
                continue
            x = dict(v)
            x['vod_id'] = key + SEP + vid
            x['vod_pic'] = self.fix_pic(key, x.get('vod_pic'))
            out.append(x)
        return out

    # ---------- 地区 ----------
    def fill_area(self, key, lst):
        """列表没带地区时，并发读详情补上（只在选了地区筛选时触发，带缓存）"""
        need = [v for v in lst if not v.get('vod_area') and v['vod_id'] not in self.area_cache]
        def one(v):
            d = self.call(key, 'detailContent', [v['vod_id'].split(SEP, 1)[1]]).get('list') or [{}]
            self.area_cache[v['vod_id']] = str(d[0].get('vod_area') or '')
        if need:
            pool = ThreadPoolExecutor(max_workers=8)
            futs = [pool.submit(one, v) for v in need[:30]]
            wait(futs, timeout=12)
            pool.shutdown(wait=False)
        for v in lst:
            if not v.get('vod_area'):
                v['vod_area'] = self.area_cache.get(v['vod_id'], '')

    def tag_area(self, v):
        reg = region_of(v.get('vod_area'))
        if reg and not str(v.get('vod_remarks', '')).startswith('【'):
            v['vod_remarks'] = f'【{reg}】' + str(v.get('vod_remarks') or '')

    # ---------- 封面 ----------
    def fix_pic(self, key, pic):
        pic = str(pic or '').strip()
        if not pic or pic.startswith('data:') or not re.match(r'^(https?:)?//', pic):
            return DEFAULT_PIC
        if pic.startswith('//'):
            pic = 'https:' + pic
        if '@Referer=' in pic or '@User-Agent=' in pic or '127.0.0.1' in pic or 'localhost' in pic:
            return pic
        if not PIC_PROXY:
            host = re.sub(r'^https?://', '', pic).split('/')[0].split(':')[0]
            ref = next((v for k, v in PIC_REFERER.items() if host.endswith(k)), None)
            if ref:
                return pic + '@Referer=' + ref
            return pic
        try:
            b = base64.urlsafe_b64encode(pic.encode()).decode()
            return f"{self.getProxyUrl()}&klimg={b}&ks={key}"
        except Exception:
            return pic

    def _img(self, param):
        url = base64.urlsafe_b64decode(param.get('klimg', '').encode()).decode()
        if url in self.img_cache:
            return self.img_cache[url]
        host = re.sub(r'^https?://', '', url).split('/')[0]
        ref = next((v for k, v in PIC_REFERER.items() if host.endswith(k)), None) or \
            re.match(r'^https?://[^/]+', url).group(0) + '/'
        tries = [url] + ([url.replace('http://', 'https://', 1)] if url.startswith('http://') else []) + [DEFAULT_PIC]
        for u in tries:
            for hd in ({'User-Agent': UAS[2], 'Referer': ref}, {'User-Agent': UAS[1]}):
                try:
                    r = BaseSpider.fetch(self, u, headers=hd, timeout=6)
                    ct = r.headers.get('Content-Type', '')
                    if r.status_code == 200 and len(r.content) > 200 and ('image' in ct or r.content[:4] in (b'\xff\xd8\xff\xe0', b'\x89PNG', b'GIF8', b'RIFF') or r.content[:3] == b'\xff\xd8\xff'):
                        res = [200, ct if 'image' in ct else 'image/jpeg', r.content]
                        if len(self.img_cache) > 300:
                            self.img_cache.clear()
                        self.img_cache[url] = res
                        return res
                except Exception:
                    continue
        return [404, 'text/plain', b'']

    def wrap_play(self, key, vod):
        urls = []
        for line in str(vod.get('vod_play_url', '')).split('$$$'):
            eps = []
            for ep in line.split('#'):
                if not ep:
                    continue
                if '$' in ep:
                    n, u = ep.split('$', 1)
                else:
                    n, u = '播放', ep
                eps.append(f'{n}${key}{SEP}{u}')
            urls.append('#'.join(eps))
        vod['vod_play_url'] = '$$$'.join(urls)
        for k in ('vod_content', 'vod_actor', 'vod_director'):
            if vod.get(k):
                vod[k] = clean_text(vod[k])
        return vod

    def site_home(self, key):
        if not (self.home_cache.get(key) or {}).get('class'):
            r = self.call(key, 'homeContent', True)
            cls = [c for c in (r.get('class') or []) if isinstance(c, dict) and c.get('type_id') is not None and c.get('type_name')
                   and not PROMO.search(str(c.get('type_name', '')))
                   and not any(w in str(c.get('type_name', '')) for w in BLOCK_WORDS)]
            if cls or key not in self.home_cache:
                self.home_cache[key] = {'class': cls, 'filters': r.get('filters') or {}}
        return self.home_cache[key]

    # ---------- 首页 ----------
    def _home_file(self):
        return os.path.join(self.cache_dir, 'home.json')

    def homeContent(self, filter):
        keys = [s[0] for s in SITES]
        disk = {}
        try:
            with open(self._home_file(), encoding='utf-8') as f:
                disk = json.load(f)
        except Exception:
            pass
        pool = ThreadPoolExecutor(max_workers=10)
        futs = {pool.submit(self.site_home, k): k for k in keys}
        # 有缓存就只等 3 秒（后台继续刷新），首次最多等 12 秒
        wait(futs, timeout=3 if disk else 12)
        pool.shutdown(wait=False)
        for k, v in disk.items():
            if k not in self.home_cache or not self.home_cache[k].get('class'):
                self.home_cache.setdefault(k, v)
                if not self.home_cache[k].get('class'):
                    self.home_cache[k] = v

        def save():
            wait(list(futs), timeout=40)
            try:
                good = {k: v for k, v in self.home_cache.items() if v.get('class')}
                good.update({k: v for k, v in disk.items() if k not in good})
                with open(self._home_file(), 'w', encoding='utf-8') as f:
                    json.dump(good, f, ensure_ascii=False)
            except Exception:
                pass
        threading.Thread(target=save, daemon=True).start()
        classes, filters = [], {}
        for s in SITES:
            key, name = s[0], s[1]
            classes.append({'type_id': key, 'type_name': name})
            h = self.home_cache.get(key)
            if not h or not h.get('class') or not isinstance(h.get('filters'), dict):
                continue
            fl = [{'key': '__c', 'name': '分类',
                   'value': [{'n': c['type_name'], 'v': str(c['type_id'])} for c in h['class']]}]
            first = str(h['class'][0]['type_id'])
            seen = {'__c'}
            for g in h['filters'].get(first, []) or []:
                if g.get('key') not in seen:
                    seen.add(g.get('key'))
                    fl.append(g)
            if key != 'douban' and not any(str(g.get('key', '')).lower() in ('area', 'region', 'diqu') or g.get('name') == '地区' for g in fl):
                fl.append({'key': '__area', 'name': '地区', 'value': [{'n': r, 'v': r} for r in AREAS]})
            filters[key] = fl
        return {'class': classes, 'filters': filters}

    def homeVideoContent(self):
        out = []
        for key in ('s007', 's024', 's010'):
            out += self.wrap(key, self.call(key, 'homeVideoContent').get('list', []))[:12]
        return {'list': out}

    # ---------- 分类 ----------
    def categoryContent(self, tid, pg, filter, extend):
        key = tid
        extend = dict(extend or {})
        h = self.site_home(key)
        sub_tid = extend.pop('__c', None) or (str(h['class'][0]['type_id']) if h['class'] else '')
        area = extend.pop('__area', '全部') or '全部'
        r = self.call(key, 'categoryContent', sub_tid, str(pg), True, extend)
        lst = self.wrap(key, r.get('list', []))
        if area != '全部' and lst:
            self.fill_area(key, lst)
            lst = [v for v in lst if region_of(v.get('vod_area')) == area]
        for v in lst:
            self.tag_area(v)
        return {'list': lst, 'page': int(r.get('page') or pg), 'pagecount': int(r.get('pagecount') or (int(pg) + (1 if lst else 0))),
                'limit': int(r.get('limit') or 20), 'total': int(r.get('total') or 9999)}

    # ---------- 详情 ----------
    def detailContent(self, ids):
        key, vid = ids[0].split(SEP, 1)
        if key == 'douban':
            r = self.call(key, 'detailContent', [vid])
            return r if r.get('list') else {'list': []}
        r = self.call(key, 'detailContent', [vid])
        lst = r.get('list') or []
        if not lst:
            return {'list': []}
        vod = dict(lst[0])
        vod['vod_id'] = ids[0]
        vod['vod_pic'] = self.fix_pic(key, vod.get('vod_pic'))
        if vod.get('vod_area'):
            reg = region_of(vod.get('vod_area'))
            vod['vod_area'] = f"{vod['vod_area']}（{reg}）" if reg and reg not in str(vod['vod_area']) else vod['vod_area']
        return {'list': [self.wrap_play(key, vod)]}

    def find_play(self, title):
        """豆瓣片名 → 去影视站搜同名，合并线路"""
        cands = ['s007', 's024', 's010', 's017', 's018', 's019', 's020', 's023', 's028', 's029']
        found = []

        def one(k):
            for v in self.call(k, 'searchContent', title, False, '1').get('list', [])[:10]:
                n = re.sub(r'^【[^】]*】', '', str(v.get('vod_name', ''))).strip()
                if n == title:
                    d = self.call(k, 'detailContent', [str(v['vod_id'])]).get('list') or []
                    if d and d[0].get('vod_play_url'):
                        return k, d[0]
            return None
        pool = ThreadPoolExecutor(max_workers=10)
        futs = [pool.submit(one, k) for k in cands]
        wait(futs, timeout=20)
        pool.shutdown(wait=False)
        for f in futs:
            if f.done() and f.result():
                found.append(f.result())
        if not found:
            return {'list': [{'vod_id': 'douban' + SEP + title, 'vod_name': title, 'vod_content': '各站暂未搜到可播放的同名片源，可用搜索换个片名试试',
                              'vod_play_from': '无', 'vod_play_url': f'暂无$douban{SEP}none'}]}
        base = dict(found[0][1])
        froms, urls = [], []
        for k, d in found:
            w = self.wrap_play(k, dict(d))
            for f_, u_ in zip(str(d.get('vod_play_from', '')).split('$$$'), w['vod_play_url'].split('$$$')):
                froms.append(f'{self.meta[k][1]}-{f_}')
                urls.append(u_)
        base.update({'vod_id': 'douban' + SEP + title, 'vod_name': title, 'vod_pic': self.fix_pic(found[0][0], base.get('vod_pic')), 'vod_play_from': '$$$'.join(froms),
                     'vod_play_url': '$$$'.join(urls)})
        return {'list': [base]}

    # ---------- 搜索 ----------
    def searchContent(self, key, quick, pg='1'):
        keys = [s[0] for s in SITES if s[4]]
        res = {}

        def one(k):
            res[k] = self.wrap(k, self.call(k, 'searchContent', key, quick, str(pg)).get('list', []))[:30]
        pool = ThreadPoolExecutor(max_workers=10)
        futs = [pool.submit(one, k) for k in keys]
        wait(futs, timeout=15)
        pool.shutdown(wait=False)
        out = []
        for k in keys:
            for v in res.get(k, []):
                reg = region_of(v.get('vod_area'))
                v['vod_name'] = f'【{self.meta[k][1]}】' + (f'【{reg}】' if reg else '') + str(v.get('vod_name', ''))
                out.append(v)
        return {'list': out, 'page': int(pg), 'pagecount': int(pg) + 1 if out else int(pg)}

    def searchContentPage(self, key, quick, pg):
        return self.searchContent(key, quick, pg)

    # ---------- 播放 ----------
    def playerContent(self, flag, id, vipFlags):
        if SEP not in id:
            return direct_or_parse(id)
        key, pid = id.split(SEP, 1)
        if key == 'douban':
            return {'parse': 0, 'url': ''}
        r = self.call(key, 'playerContent', flag, pid, vipFlags)
        if not r or not r.get('url'):
            return direct_or_parse(pid)
        if 'header' not in r:
            r['header'] = {'User-Agent': UAS[2]}
        return r

    def isVideoFormat(self, url):
        return bool(re.search(r'\.(m3u8|mp4|flv|mkv)(\?|$)', url or '', re.I))

    def manualVideoCheck(self):
        pass

    def localProxy(self, param):
        if (param or {}).get('klimg'):
            return self._img(param)
        key = (param or {}).get('klsite')
        if key and key in self.subs and self.subs[key] is not None:
            p = dict(param)
            p.pop('klsite', None)
            try:
                return self.subs[key].localProxy(p)
            except Exception:
                return None
        for s in self.subs.values():          # 兜底：挨个试
            try:
                r = s.localProxy(param) if s else None
                if r:
                    return r
            except Exception:
                continue
        return None

    def liveContent(self, url):
        return ''

    def destroy(self):
        for s in self.subs.values():
            try:
                s.destroy()
            except Exception:
                pass

